mapper.select:
SELECT p."id", p."user_id", p."category_id", p."title", p."slug", p."cover_image", p."status", p."is_top", p."view_count", p."like_count", p."comment_count", p."created_at", COALESCE(u."nickname", u."username") AS "author_name", c."name" AS "category_name" FROM "BLOG"."posts" p LEFT JOIN "BLOG"."users" u ON u."id"=p."user_id" LEFT JOIN "BLOG"."categories" c ON c."id"=p."category_id" WHERE p."deleted_at" IS NULL
AND p."status"=1 AND p."status"=#{query.status}
AND p."category_id"=#{query.categoryId}
AND p."user_id"=#{query.authorId}
AND EXISTS (SELECT 1 FROM "BLOG"."post_tags" pt WHERE pt."post_id"=p."id" AND pt."tag_id"=#{query.tagId})
AND (p."user_id"=#{viewerId} OR p."status"=1)
AND (p."title" LIKE #{pattern} OR p."slug" LIKE #{pattern} OR u."nickname" LIKE #{pattern} OR u."username" LIKE #{pattern} OR CAST(p."id" AS VARCHAR(30)) LIKE #{pattern})
ORDER BY
p."view_count" DESC, p."like_count" DESC, p."created_at" DESC, p."is_top" DESC, p."created_at" DESC,
p."id" DESC
